#!/usr/bin/env python3
"""Focused regression check for the oe-41-grub2 UFS symlink bounded-copy fix.

Usage: ufs_fix_check.py <checkout>

1. Structural check on the candidate source:
   - grub-core/fs/ufs.c must use grub_strlcpy(symlink, data->inode.symlink, sz)
   - grub-core/fs/ufs.c must not use grub_strcpy(symlink, ...)
2. Security-invariant check using the real target code text:
   - extracts grub_strlcpy() from <checkout>/include/grub/misc.h
   - extracts grub_strcpy() from <checkout>/grub-core/kern/misc.c
   - compiles a harness under AddressSanitizer and runs two cases on a
     non-NUL-terminated inline-symlink-sized source:
       vulnerable: grub_strcpy into an sz+1 heap buffer -> must be detected
       fixed:      grub_strlcpy(..., sz) into an sz+1 heap buffer -> must be clean
   Exit 0 only if all assertions pass.
"""
import os
import re
import subprocess
import sys
import tempfile

sz = 60  # UFS1 inline symlink storage: (GRUB_UFS_DIRBLKS + GRUB_UFS_INDIRBLKS) * 4


def read(path):
    with open(path, "r", encoding="utf-8", errors="replace") as fh:
        return fh.read()


def extract_function(text, signature_re):
    m = re.search(signature_re, text)
    if not m:
        raise SystemExit("could not locate function via %r" % signature_re)
    start = m.start()
    depth = 0
    seen = False
    i = start
    while i < len(text):
        ch = text[i]
        if ch == "{":
            depth += 1
            seen = True
        elif ch == "}":
            depth -= 1
            if seen and depth == 0:
                return text[start:i + 1]
        i += 1
    raise SystemExit("unbalanced braces while extracting function")


def main():
    if len(sys.argv) != 2:
        raise SystemExit("usage: ufs_fix_check.py <checkout>")
    root = os.path.abspath(sys.argv[1])

    ufs = read(os.path.join(root, "grub-core/fs/ufs.c"))
    misc = read(os.path.join(root, "include/grub/misc.h"))
    kern = read(os.path.join(root, "grub-core/kern/misc.c"))

    failures = []

    # --- 1. candidate source checks -------------------------------------
    if "grub_strlcpy (symlink, (char *) data->inode.symlink, sz)" not in ufs:
        failures.append("ufs.c does not contain the bounded grub_strlcpy call")
    if re.search(r"grub_strcpy \(symlink,", ufs):
        failures.append("ufs.c still contains an unbounded grub_strcpy(symlink, ...) call")
    if "grub_strlcpy" not in misc:
        failures.append("target include/grub/misc.h does not define grub_strlcpy")

    if failures:
        for f in failures:
            print("FAIL:", f)
        return 1
    print("source checks: OK")

    # --- 2. extract the real target implementations ----------------------
    strlcpy = extract_function(
        misc,
        r"static\s+inline\s+grub_size_t\s*\ngrub_strlcpy\s*\(char \*dest, const char \*src, grub_size_t size\)")
    strcpy_impl = extract_function(
        kern, r"\nchar \*\ngrub_strcpy\s*\(char \*dest, const char \*src\)")
    print("extracted grub_strlcpy (%d bytes) and grub_strcpy (%d bytes)"
          % (len(strlcpy), len(strcpy_impl)))

    harness_template = r"""
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
typedef unsigned long grub_size_t;
#define SZ %(sz)d

%(impl)s

int run_%(tag)s (void)
{
  /* source has exactly SZ bytes and no NUL terminator (crafted inline symlink) */
  char *src = (char *) malloc (SZ);
  char *dst = (char *) malloc (SZ + 1);
  if (!src || !dst) return 2;
  memset (src, 'A', SZ);
  memset (dst, 'B', SZ + 1);
%(call)s
  /* the bounded copy must terminate within the allocation */
  dst[SZ] = '\0';
  printf ("%(tag)s: dst[0]=%%c dst[SZ-1]=%%d dst[SZ]=%%d\n",
          dst[0], (int) dst[SZ - 1], (int) dst[SZ]);
  free (src);
  free (dst);
  return 0;
}

int main (void) { return run_%(tag)s (); }
"""

    with tempfile.TemporaryDirectory(prefix="ufs-fix-check-") as tmp:
        vuln_c = os.path.join(tmp, "vuln.c")
        fixed_c = os.path.join(tmp, "fixed.c")
        with open(vuln_c, "w") as fh:
            fh.write(harness_template % {
                "sz": sz,
                "impl": strcpy_impl,
                "tag": "vuln",
                "call": "  grub_strcpy (dst, src);  /* unbounded: mimics pre-fix ufs.c */",
            })
        with open(fixed_c, "w") as fh:
            fh.write(harness_template % {
                "sz": sz,
                "impl": strlcpy,
                "tag": "fixed",
                "call": "  grub_strlcpy (dst, src, SZ);  /* candidate fix */",
            })

        def compile_and_run(src_file, exe):
            cc = subprocess.run(
                ["gcc", "-O1", "-g", "-fsanitize=address", "-fno-omit-frame-pointer",
                 "-o", exe, src_file],
                capture_output=True, text=True)
            if cc.returncode != 0:
                print("compile failed for", src_file)
                print(cc.stderr)
                return None
            return subprocess.run([exe], capture_output=True, text=True)

        print("== vulnerable primitive (pre-fix grub_strcpy) ==")
        vuln = compile_and_run(vuln_c, os.path.join(tmp, "vuln"))
        if vuln is None:
            return 1
        print(vuln.stdout, end="")
        print(vuln.stderr, end="")
        asan_vuln = "AddressSanitizer" in (vuln.stderr or "") or vuln.returncode != 0

        print("== candidate fix (grub_strlcpy(...,sz)) ==")
        fixed = compile_and_run(fixed_c, os.path.join(tmp, "fixed"))
        if fixed is None:
            return 1
        print(fixed.stdout, end="")
        print(fixed.stderr, end="")
        fixed_ok = fixed.returncode == 0 and "AddressSanitizer" not in (fixed.stderr or "")

    print("vulnerable primitive detected overflow:", asan_vuln)
    print("candidate bounded copy clean:", fixed_ok)
    if not (asan_vuln and fixed_ok):
        print("FAIL: security invariant not demonstrated")
        return 1
    print("security invariant: OK")
    return 0


if __name__ == "__main__":
    sys.exit(main())

