/* Model the real inode: the inline symlink array (SZ bytes) sits inside a
   larger attacker-controlled object, so reading past symlink stays inside the
   allocation, but the *write* target is only SZ+1 bytes. */
#define SRCSZ (SZ + 128)

int run_%(tag)s (void)
{
  char *src = (char *) malloc (SRCSZ);
  char *dst = (char *) malloc (SZ + 1);
  if (!src || !dst) return 2;
  memset (src, 'A', SRCSZ);      /* no NUL for SRCSZ-1 bytes */
  src[SRCSZ - 1] = '\0';
  memset (dst, 'B', SZ + 1);     /* sentinel: dst[SZ] must stay 'B' */
%(call)s
  /* the bounded copy must terminate within the SZ+1 destination */
  printf ("%(tag)s: dst[0]=%%c dst[SZ-1]=%%d dst[SZ]=%%c\n",
          dst[0], (int) dst[SZ - 1], dst[SZ]);
  free (src);
  free (dst);
  return 0;
}

